-- ============================================
-- seed_all.sql  —  Combined seed data
-- ============================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;


-- >>> tb_shop (seed_shops.sql)
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- Seed data for tb_shop (27 rows) — idempotent (ON DUPLICATE KEY UPDATE)
ON DUPLICATE KEY UPDATE
  `name`=VALUES(`name`),
  `type_id`=VALUES(`type_id`),
  `images`=VALUES(`images`),
  `area`=VALUES(`area`),
  `address`=VALUES(`address`),
  `x`=VALUES(`x`),
  `y`=VALUES(`y`),
  `avg_price`=VALUES(`avg_price`),
  `sold`=VALUES(`sold`),
  `comments`=VALUES(`comments`),
  `score`=VALUES(`score`),
  `open_hours`=VALUES(`open_hours`),
  `create_time`=VALUES(`create_time`),
  `update_time`=VALUES(`update_time`);


SET FOREIGN_KEY_CHECKS = 1;

-- >>> tb_voucher (seed_vouchers.sql)
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- Seed data for tb_voucher (16 rows) — idempotent (ON DUPLICATE KEY UPDATE)
ON DUPLICATE KEY UPDATE
  `shop_id`=VALUES(`shop_id`),
  `title`=VALUES(`title`),
  `sub_title`=VALUES(`sub_title`),
  `rules`=VALUES(`rules`),
  `pay_value`=VALUES(`pay_value`),
  `actual_value`=VALUES(`actual_value`),
  `type`=VALUES(`type`),
  `status`=VALUES(`status`),
  `create_time`=VALUES(`create_time`),
  `update_time`=VALUES(`update_time`);


SET FOREIGN_KEY_CHECKS = 1;
